const STORE='bike-doctor-prototype-v2';
function repairSavedWorkspace(data){
  if(!data||typeof data!=='object'||Array.isArray(data))data=structuredClone(seed);
  for(const [key,defaults]of Object.entries(seed)){
    if(Array.isArray(defaults))data[key]=Array.isArray(data[key])?data[key].filter(row=>row&&typeof row==='object'&&!Array.isArray(row)):[];
    else if(key==='settings')data.settings={...defaults,...(data.settings&&typeof data.settings==='object'?data.settings:{})};
    else if(key==='lists'){
      const saved=data.lists&&typeof data.lists==='object'?data.lists:{};
      data.lists={...structuredClone(defaults),...saved};
      for(const [listName,values]of Object.entries(defaults))if(!Array.isArray(data.lists[listName]))data.lists[listName]=structuredClone(values);
    }else if(defaults&&typeof defaults==='object')data[key]={...defaults,...(data[key]&&typeof data[key]==='object'?data[key]:{})};
  }
  for(const key of ['stockMovements','attachments','trash','vehicleModels'])if(!Array.isArray(data[key]))data[key]=[];
  return data;
}
let db;
try{db=repairSavedWorkspace(JSON.parse(localStorage.getItem(STORE))||structuredClone(seed))}catch{db=repairSavedWorkspace(structuredClone(seed))}
let page='dashboard',search='',filter='',reportFrom='',reportTo='',tabState='customers',listName='Vehicle Brands',editing=null,jobDraft=null,lastFocus=null;
const prefixes={customers:'BD-CUST',bikes:'BD-VEH',services:'BD-SVC',staff:'BD-STF',parts:'BD-PRT',jobs:'BD-JOB',sales:'BD-SALE',purchases:'BD-PUR',appointments:'BD-APT',insurance:'BD-INS',expenses:'BD-EXP',accounts:'BD-ACC',receipts:'BD-TXN',users:'BD-USR'};
const find=(key,id)=>db[key]?.find(x=>x.id===id);
const name=(key,id)=>find(key,id)?.name||'—';
const number=id=>find('bikes',id)?.number||'—';
function nextId(key){let prefix=key==='jobs'?db.settings.jobPrefix:key==='customers'?db.settings.customerPrefix:key==='bikes'?db.settings.vehiclePrefix:prefixes[key];let n=Math.max(1000,...[...db[key],...(key==='staff'?Object.values(db.attendance||{}).flatMap(records=>Object.keys(records||{}).map(id=>({id}))):[])].filter(x=>key!=='staff'||/^BD-STF-[1-9]\d{3,11}$/.test(x.id)).map(x=>Number(x.id.match(/(\d+)$/)?.[1])||1000))+1;return `${prefix||prefixes[key]}-${n}`}
function save(message){window.BD_LAST_SAVE_ERROR=null;try{localStorage.setItem(STORE,JSON.stringify(db))}catch(error){window.BD_LAST_SAVE_ERROR=error;toast('Browser storage is full. Export a backup before continuing.');return false}if(message)toast(message);return true}
function audit(action,detail){db.audit.unshift({id:'EVT-'+Date.now(),date:new Date().toISOString(),user:'admin',module:titles[page]||page,action,detail,status:'Success'})}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3500)}
const opts=(arr,value)=>arr.map(v=>{let a=typeof v==='object'?v:{value:v,label:v};return `<option value="${esc(a.value)}" ${String(a.value)===String(value)?'selected':''}>${esc(a.label)}</option>`}).join('');
const badge=s=>`<span class="badge ${['Active','Completed','Delivered','Fully Paid','In Stock','Present','Confirmed'].includes(s)?'good':['Pending','Low Stock','Partially Paid','Waiting for Parts','Half Day'].includes(s)?'warn':['Cancelled','Out of Stock','Absent','Unpaid'].includes(s)?'bad':'info'}">${esc(s)}</span>`;
function billTotals(b){const labour=(b.serviceLines||[]).reduce((s,x)=>s+Number(x.charge||0),0);const parts=(b.partLines||[]).reduce((s,x)=>s+Number(x.qty)*Number(x.price),0);const partTax=(b.invoiceType==='non-gst'?[]:b.partLines||[]).reduce((s,x)=>s+Number(x.qty)*Number(x.price)*Number(x.gst||0)/100,0);const discount=Number(b.discount||0);const taxable=Math.max(0,labour+parts-discount);const tax=round(partTax+labour*Number(b.invoiceType==='non-gst'?0:b.tax||0)/100);return {labour:round(labour),parts:round(parts),tax,total:round(taxable+tax)}}
function paid(b){return round(Number(b.advance||0)+db.receipts.filter(x=>x.bill===b.id).reduce((s,x)=>s+Number(x.amount),0))}
const due=b=>Math.max(0,round(billTotals(b).total-paid(b)));
const payStatus=b=>due(b)<=0?'Fully Paid':paid(b)>0?'Partially Paid':'Unpaid';
function allReceipts(){return [...(db.jobs||[]),...(db.sales||[])].filter(b=>Number(b.advance)>0&&b.status!=='Cancelled').map(b=>({id:b.id+'-ADV',date:b.date,bill:b.id,amount:b.advance,account:b.account,mode:b.mode||'Cash',party:b.customer?name('customers',b.customer):b.walkin||'Walk-in Customer'})).concat((db.receipts||[]).map(r=>({...r,party:r.party||(find('jobs',r.bill)?.customer?name('customers',find('jobs',r.bill).customer):'Walk-in Customer')})))}
function stock(id,exclude){let p=find('parts',id);if(!p)return 0;let qty=Number(p.opening||0);for(let purchase of db.purchases.filter(x=>x.id!==exclude))for(let l of purchase.partLines||[])if(l.part===id)qty+=Number(l.qty);for(let bill of [...db.jobs,...db.sales].filter(x=>x.id!==exclude&&x.status!=='Cancelled'))for(let l of bill.partLines||[])if(l.part===id)qty-=Number(l.qty);return round(qty)}
const stockStatus=p=>stock(p.id)<=0?'Out of Stock':stock(p.id)<=Number(p.min)?'Low Stock':'In Stock';
function accountBalance(id){let val=Number(find('accounts',id)?.opening||0);for(let b of [...db.jobs,...db.sales])if(b.account===id&&b.status!=='Cancelled')val+=Number(b.advance||0);for(let r of db.receipts)if(r.account===id)val+=Number(r.amount);for(let b of db.purchases)if(b.account===id)val-=Number(b.advance||0);for(let e of db.expenses)if(e.account===id)val-=Number(e.amount);return round(val)}
function nav(){let html='';for(let [group,items] of groups){html+=`<h3>${group}</h3>`;for(let [key,title,i]of items){html+=`<a href="#${key}" data-page="${key}" class="${page===key||(key==='reports'&&page.startsWith('report-'))?'active':''}">${icon(i)}<span>${title}</span>${key==='reports'?'<span style="margin-left:auto">⌄</span>':''}</a>`;if(key==='reports'&&(page==='reports'||page.startsWith('report-')))html+=`<div class="reportchildren">${reports.map(([k,t])=>`<a href="#${k}" data-page="${k}" class="${page===k?'active':''}">${t}</a>`).join('')}</div>`}}$('#navigation').innerHTML=html}
async function syncCustomersFromCloud(){try{let response=await fetch('/api/customers');if(!response.ok)return;let payload=await response.json();if(!Array.isArray(payload.data))return;db.customers=payload.data.map(c=>({...c,alt:c.alt_mobile||c.alt||''}));save();if(page==='customers')render()}catch(error){console.warn('Cloud customer sync unavailable',error)}}
async function syncCustomerToCloud(record){try{let response=await fetch('/api/customers',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(record)});if(!response.ok)throw new Error(`HTTP ${response.status}`);return true}catch(error){console.warn('Cloud customer save unavailable',error);toast('Saved locally; cloud sync is unavailable.');return false}}
function go(key){page=key==='reports'?'report-sales':key;search='';filter='';reportFrom='';reportTo='';tabState=key==='payments'?'customers':'list';document.body.classList.remove('navopen');location.hash=page;render();window.scrollTo(0,0);if(page==='customers')syncCustomersFromCloud()}
function btn(label,action,cls='',ico){return `<button type="button" class="btn ${cls}" data-action="${action}">${ico?icon(ico):''}${label}</button>`}
function table(headers,rows){return `<div class="tablewrap"><table><thead><tr>${headers.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(r=>`<tr>${r.map(c=>`<td>${c??'—'}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${headers.length}" class="empty">${icon('box')}No records match this view.<br>Add a record or adjust your search.</td></tr>`}</tbody></table></div>`}
function summary(items){return `<div class="summary">${items.map(([t,v])=>`<div class="summaryitem"><small>${t}</small><strong>${v}</strong></div>`).join('')}</div>`}
function serviceMasterPage(rows){let services=db.services;let cards=[['TOTAL SERVICES',services.length,'sparkle','service-kpi-dark'],['ACTIVE SERVICES',services.filter(s=>s.status==='Active').length,'shield','service-kpi-green'],['AVERAGE LABOUR CHARGE',money(services.reduce((sum,s)=>sum+Number(s.charge||0),0)/Math.max(services.length,1)),'calculator','service-kpi-blue'],['HIGHEST CHARGE',money(Math.max(0,...services.map(s=>Number(s.charge)||0))),'tag','service-kpi-orange']];return `<section class="service-master-page"><div class="service-kpis">${cards.map(([label,value,ico,color])=>`<article class="service-kpi ${color}"><span class="service-kpi-icon">${icon(ico)}</span><span class="service-kpi-copy"><small>${label}</small><strong>${value}</strong></span></article>`).join('')}</div><div class="service-filters"><input class="search" id="search" aria-label="Search services" placeholder="Search service name, category, description…" value="${esc(search)}"><select id="filter" aria-label="Category filter"><option value="">All Categories</option>${opts(db.lists['Service Categories'],filter)}</select></div><div class="toolbar service-actions"><span class="spacer"></span>${btn('Export Excel','export','exportButton','download')}${btn('Add New Service','add','','plus')}</div>${table(['Service ID','Service Name','Category','Standard Labour Charge (₹)','Description','Status','Actions'],rows.map(s=>[esc(s.id),`<strong>${esc(s.name)}</strong>`,esc(s.category),money(s.charge),esc(s.description||'—'),badge(s.status),actions('services',s.id)]))}</section>`}function toolbar(add,extra=''){return `<div class="toolbar"><input class="search" id="search" aria-label="Search records" placeholder="Search by name, number or ID…" value="${esc(search)}">${extra}<span class="spacer"></span>${btn('Export Excel','export','success','download')}${add?btn(add,'add','','plus'):''}</div>`}
function actions(key,id,extra=''){return `<div class="rowactions">${extra}<button class="btn secondary small" title="Edit record" aria-label="Edit ${esc(id)}" data-edit="${key}|${esc(id)}">${icon('edit')}</button><button class="btn danger small" title="Delete record" aria-label="Delete ${esc(id)}" data-delete="${key}|${esc(id)}">${icon('trash')}</button></div>`}
function matches(record){if(!search)return true;const haystack=Object.entries(record).filter(([k])=>!['permissions'].includes(k)).map(([,v])=>typeof v==='object'?'':v).join(' ').toLowerCase();const terms=search.toLowerCase().trim().split(/\s+/).filter(Boolean);return terms.some(term=>haystack.includes(term))}
function chartSvg(values,color){let max=Math.max(...values,1),points=values.map((v,i)=>`${40+i*54},${140-v/max*110}`).join(' ');return `<svg viewBox="0 0 350 170" class="chartsvg"><defs><linearGradient id="fade-${color.slice(1)}" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="${color}" stop-opacity=".18"/><stop offset="100%" stop-color="${color}" stop-opacity="0"/></linearGradient></defs>${[30,65,100,140].map(y=>`<line x1="36" y1="${y}" x2="320" y2="${y}" stroke="#e2e8f0" stroke-dasharray="3 4"/>`).join('')}<polygon points="40,140 ${points} 310,140" fill="url(#fade-${color.slice(1)})"/><polyline points="${points}" stroke="${color}" stroke-width="2.5" fill="none"/>${values.map((v,i)=>`<circle cx="${40+i*54}" cy="${140-v/max*110}" r="3.5" fill="white" stroke="${color}" stroke-width="2"/>`).join('')}${monthLabels().map((m,i)=>`<text x="${40+i*54}" y="163" font-size="10" text-anchor="middle" fill="#94a3b8">${m}</text>`).join('')}</svg>`}
function monthKeys(){const [year,month]=today().slice(0,7).split('-').map(Number);return Array.from({length:6},(_,i)=>new Date(Date.UTC(year,month-6+i,1)).toISOString().slice(0,7))}
function monthLabels(){return monthKeys().map(key=>new Date(`${key}-01T12:00:00Z`).toLocaleString('en',{month:'short',timeZone:'UTC'}))}
function monthValues(profit=false){return monthKeys().map(ym=>[...db.jobs,...db.sales].filter(b=>b.date?.startsWith(ym)&&b.status!=='Cancelled').reduce((s,b)=>s+billTotals(b).total-(profit?(Number(billTotals(b).tax||0)+(b.partLines||[]).reduce((a,l)=>a+Number(find('parts',l.part)?.purchase||0)*Number(l.qty||0),0)):0),0))}
function dashboard(){let bills=[...db.jobs,...db.sales].filter(b=>b.status!=='Cancelled'),revenue=bills.reduce((s,b)=>s+billTotals(b).total,0),dues=bills.reduce((s,b)=>s+due(b),0);let cards=[['CUSTOMERS',db.customers.length,'Total Registered','users','blue','customers'],['VEHICLES',db.bikes.length,'Registered Vehicles','bike','purple','bikes'],['ACTIVE JOBS',db.jobs.filter(b=>!['Completed','Delivered','Cancelled'].includes(b.status)).length,'Pending + In Progress','wrench','navy','jobs'],['REVENUE',money(revenue),'Total Billed Amount','wallet','green','report-sales'],['DUES',money(dues),'Outstanding Amount','shield','red','payments'],['EXPENSES',money(db.expenses.reduce((s,e)=>s+Number(e.amount),0)),'Total Spent','wallet','amber','expenses']];return `<div class="cards">${cards.map(([t,v,d,i,c,p])=>`<article class="stat ${c}"><div class="statmain"><div class="statlabel">${icon(i)}${t}</div><div class="statvalue">${v}</div><div class="statdesc">${d}</div></div><div class="watermark">${icon(i)}</div><button class="statmore" data-page="${p}">More info <span>➜</span></button></article>`).join('')}</div><div class="chartgrid"><section class="panel"><div class="panelhead"><h2>${icon('chart')}Job Status Overview</h2></div><div class="chart"><div class="donut" style="${jobDonut()}"><strong>${db.jobs.length}<small>TOTAL JOBS</small></strong></div><div class="legend">${['Pending','In Progress','Completed','Delivered'].map((s,i)=>`<div><i style="background:${['#f59e0b','#3b82f6','#10b981','#6366f1'][i]}"></i>${s} <b>${db.jobs.filter(j=>j.status===s).length}</b></div>`).join('')}</div></div></section><section class="panel"><div class="panelhead"><h2>${icon('chart')}Monthly Revenue (Last 6 Months)</h2></div><div class="chart">${chartSvg(monthValues(),'#3b82f6')}</div></section><section class="panel"><div class="panelhead"><h2>${icon('chart')}Gross Margin Trend (Last 6 Months)</h2></div><div class="chart">${chartSvg(monthValues(true),'#10b981')}</div></section><section class="panel"><div class="panelhead"><h2>${icon('wrench')}Quick Access</h2></div><div class="panelbody quickactions">${[['customers','Add Customer','users'],['bikes','Add Vehicle','bike'],['jobs','New Job Card','clipboard'],['parts','Add Part','box'],['purchases','New Purchase','cart'],['expenses','Add Expense','wallet']].map(([k,t,i])=>`<button class="quick" data-new="${k}">${icon(i)}${t}</button>`).join('')}</div></section></div><section class="panel"><div class="panelhead"><h2>Recent Job Cards</h2><button class="linkbutton" data-page="jobs">View All →</button></div>${table(['Job No','Customer','Vehicle','Status','Amount'],db.jobs.slice(-5).reverse().map(j=>[`<strong>${esc(j.id)}</strong>`,esc(name('customers',j.customer)),esc(number(j.bike)),badge(j.status),money(billTotals(j).total)]))}</section><section class="panel"><div class="panelhead"><h2>Recent Transactions</h2><button class="linkbutton" data-page="payments">View All →</button></div>${table(['Date','Type','Party','Amount','Status'],allReceipts().slice(-5).reverse().map(r=>[esc(r.date),'Customer Receipt',esc(r.party),money(r.amount),badge('Received')]))}</section>`}
function jobDonut(){let colors={'Pending':'#f59e0b','In Progress':'#3b82f6','Waiting for Parts':'#f97316','Completed':'#10b981','Delivered':'#6366f1','Cancelled':'#cbd5e1'},n=db.jobs.length;if(!n)return 'background:#e2e8f0';let start=0,segs=[];for(let [status,color]of Object.entries(colors)){let end=start+db.jobs.filter(j=>j.status===status).length/n*100;if(end>start)segs.push(`${color} ${start}% ${end}%`);start=end}return `background:conic-gradient(${segs.join(',')})`}
function basicPage(key){let rows=db[key].filter(matches);if(filter)rows=rows.filter(x=>[x.status,x.category,x.type].includes(filter));switch(key){case'customers':return toolbar('Add Customer')+table(['Customer ID','Customer Name','Mobile Number','Alt Mobile','Email ID','Address','City','State','PIN','GST Number','Type','DOB','Actions'],rows.map(c=>[esc(c.id),`<strong>${esc(c.name)}</strong>`,esc(c.mobile),esc(c.alt||'—'),esc(c.email||'—'),esc(c.address||'—'),esc(c.city||'—'),esc(c.state||'—'),esc(c.pin||'—'),esc(c.gst||'—'),badge(c.type),esc(c.dob||'—'),actions(key,c.id)]));case'services':return serviceMasterPage(rows);case'staff':return toolbar('Add Staff')+table(['Staff ID','Staff Name','Designation','Mobile Number','Specialization','Experience (Yrs)','Salary','Identity Details','Status','Actions'],rows.map(s=>[esc(s.id),`<strong>${esc(s.name)}</strong>`,esc(s.designation),esc(s.mobile),esc(s.skills||'—'),esc(s.experience||0),s.salaryType==='Per Job'?`${esc(s.salary)}% (Per Job)`:money(s.salary)+` (${esc(s.salaryType)})`,[s.aadhaar?'Aadhaar saved':'',s.drivingLicense?'Driving licence saved':''].filter(Boolean).join(' · ')||'Not added',badge(s.status),actions(key,s.id)]));case'accounts':return summary([['TOTAL LIQUID FUNDS',money(db.accounts.reduce((s,a)=>s+accountBalance(a.id),0))],['CASH IN HAND',money(db.accounts.filter(a=>a.type==='Cash in Hand').reduce((s,a)=>s+accountBalance(a.id),0))],['BANK ACCOUNTS',money(db.accounts.filter(a=>a.type.includes('Bank')).reduce((s,a)=>s+accountBalance(a.id),0))],['UPI & ONLINE QR',money(db.accounts.filter(a=>a.type.includes('UPI')).reduce((s,a)=>s+accountBalance(a.id),0))]])+toolbar('Add New Account')+table(['Account ID','Account Name','Account Type','Opening Balance','Current Balance','Status','Actions'],rows.map(a=>[esc(a.id),`<strong>${esc(a.name)}</strong>`,esc(a.type),money(a.opening),money(accountBalance(a.id)),badge(a.status),actions(key,a.id,`<button class="btn secondary small" data-ledger="${esc(a.id)}">Statement</button>`)]));case'parts':return summary([['TOTAL SPARE PARTS',db.parts.length],['MAIN STOCK VALUE',money(db.parts.reduce((s,p)=>s+stock(p.id)*p.purchase,0))],['LOW STOCK ITEMS',db.parts.filter(p=>stockStatus(p)==='Low Stock').length],['OUT OF STOCK',db.parts.filter(p=>stock(p.id)<=0).length]])+toolbar('Add Spare Part',`<select id="stockFilter" aria-label="Stock status"><option value="">All Stock Status</option>${opts(['In Stock','Low Stock','Out of Stock'],filter)}</select>`)+table(['Part Code / SKU','Part Name','HSN Code','Category','Part Brand','Vehicle Make','Vehicle Model','Vendor Name(s)','Purchase Date','Purchase Price','Selling Price','Opening Stock','Main Stock','Status','Rack No.','Actions'],db.parts.filter(p=>matches({...p,vendors:partVendorNames(p.id)})).filter(p=>!filter||stockStatus(p)===filter).map(p=>[esc(p.id),`<strong>${esc(p.name)}</strong>`,esc(p.hsn||'—'),esc(p.category),esc(p.brand||'—'),esc(p.vehicleMake||'—'),esc(p.vehicleModel||'—'),partVendorMarkup(p.id),esc(partPurchaseDate(p)||'—'),money(p.purchase),money(p.price),esc(p.opening)+' '+esc(p.unit),stock(p.id)+' '+esc(p.unit),badge(stockStatus(p)),esc(p.rack||'—'),actions(key,p.id)]));case'insurance':return summary([['TOTAL POLICIES',db.insurance.length],['ACTIVE INSURANCE',db.insurance.filter(i=>i.expiry>=today()).length],['EXPIRING SOON (30 DAYS)',db.insurance.filter(i=>i.expiry>=today()&&(new Date(i.expiry)-new Date(today()))/86400000<=30).length],['EXPIRED INSURANCE',db.insurance.filter(i=>i.expiry<today()).length]])+toolbar('Add Insurance')+table(['Vehicle No','Customer','Policy / Provider','Issue Date','Expiry Date','Status','Actions'],rows.map(i=>[esc(number(i.bike)),esc(name('customers',find('bikes',i.bike)?.customer)),`${esc(i.policy||'—')}<small>${esc(i.provider)}</small>`,esc(i.issue),esc(i.expiry),badge(i.expiry>=today()?'Active':'Expired'),actions(key,i.id)]));case'expenses':return `<div class="intro"><h2>Garage Expenses Management</h2><p>Track operational expenses, staff payouts and account outflows.</p></div>`+summary([['TOTAL EXPENSES',money(db.expenses.reduce((s,e)=>s+Number(e.amount),0))],['THIS MONTH',money(db.expenses.filter(e=>e.date.startsWith(today().slice(0,7))).reduce((s,e)=>s+Number(e.amount),0))],['TODAY',money(db.expenses.filter(e=>e.date===today()).reduce((s,e)=>s+Number(e.amount),0))],['TOTAL ENTRIES',db.expenses.length]])+toolbar('Add Expense')+table(['Expense ID','Date','Category','Amount','Payment Mode','Account','Description','Actions'],rows.map(e=>[esc(e.id),esc(e.date),esc(e.category),money(e.amount),esc(e.mode),esc(name('accounts',e.account)),esc(e.description||'—'),actions(key,e.id)]));case'users':return `<div class="notice">Administrators manage server user accounts, passwords and module permissions here.</div>`+toolbar('Add New User')+table(['User','Name','Role','Password','Permissions','Actions'],rows.map(u=>[`<span class="avatar">${esc((u.name||'?')[0])}</span>`,`<strong>${esc(u.name)}</strong><small style="display:block;color:#64748b">User ID: ${esc(u.username||u.id)}</small>`,badge(u.role),u.passwordHash?'••••••':'Not set',`${window.BD_USER_ACCESS_COUNT?window.BD_USER_ACCESS_COUNT(u):0} / ${window.BD_USER_PERMISSION_MODULE_COUNT||20} Modules`,actions(key,u.id)]));}}
function vehicleAmcSummary(b){
 if(b.amcScope!=='vehicle'||!b.amcType)return badge('Non-AMC');
 let status='Incomplete',date=today();
 if(/^\d{4}-\d{2}-\d{2}$/.test(b.amcStart||'')&&/^\d{4}-\d{2}-\d{2}$/.test(b.amcExpiry||'')&&b.amcExpiry>=b.amcStart)status=b.amcStart>date?'Not Started':b.amcExpiry<date?'Expired':'Active';
 let cls=status==='Active'?'good':status==='Expired'?'bad':status==='Incomplete'?'warn':'info';
 let until=b.amcExpiry?(typeof displayDate==='function'?displayDate(b.amcExpiry):b.amcExpiry):'';
 return `<span class="badge ${cls}">AMC · ${status}</span>${until?`<small>Valid until ${esc(until)}</small>`:''}`
}
function bikesPage(){
 let rows=db.bikes.filter(b=>matches({...b,customerName:name('customers',b.customer),customerMobile:find('customers',b.customer)?.mobile||''}));
 let controls='';
 let content=rows.length?table(['Vehicle No.','Vehicle Make / Model','Customer','Mobile','Type','AMC Coverage','Fuel / Transmission','Actions'],rows.map(b=>[`<strong>${esc(b.number)}</strong><small>${esc(b.id)}</small>`,`<strong>${esc(b.brand)} ${esc(b.model)}</strong><small>${esc([b.variant,b.year].filter(Boolean).join(' · ')||'—')}</small>`,esc(name('customers',b.customer)),esc(find('customers',b.customer)?.mobile||'—'),badge(b.type),vehicleAmcSummary(b),`${esc(b.fuel||'—')}<small>${esc(b.transmission||'—')}</small>`,actions('bikes',b.id)])):'<div class="empty">No vehicles found. Add a vehicle to get started.</div>';
 return toolbar('Add Vehicle').replace('Search by name, number or ID…','Search by vehicle number, customer name or mobile number…')+controls+content
}
function paymentsPage(){let bills=[...db.jobs,...db.sales].filter(b=>b.status!=='Cancelled');return summary([['CUSTOMER DUES (RECEIVABLE)',money(bills.reduce((s,b)=>s+due(b),0))],['SUPPLIER DUES (PAYABLE)',money(db.purchases.reduce((s,b)=>s+due(b),0))],['TOTAL CUSTOMER COLLECTED',money(allReceipts().reduce((s,r)=>s+Number(r.amount),0))],['TOTAL SUPPLIER PAID',money(db.purchases.reduce((s,b)=>s+Number(b.advance||0),0))]])+`<div class="tabs">${[['customers','Customer Receivable'],['suppliers','Supplier Payable'],['history','Payment Audit History']].map(([k,t])=>`<button class="tab ${tabState===k?'active':''}" data-tab="${k}">${t}</button>`).join('')}</div>`+toolbar('')+(tabState==='history'?table(['Txn ID','Date','Party','Bill ID','Amount','Mode','Account'],allReceipts().filter(matches).map(r=>[esc(r.id),esc(r.date),esc(r.party),esc(r.bill),money(r.amount),esc(r.mode),esc(name('accounts',r.account))])):tabState==='suppliers'?table(['Purchase ID','Supplier','Date','Invoice Total','Paid','Due','Status'],db.purchases.filter(matches).map(b=>[esc(b.id),esc(b.supplier),esc(b.date),money(billTotals(b).total),money(paid(b)),money(due(b)),badge(payStatus(b))])):table(['Bill ID','Customer','Vehicle','Date','Grand Total','Paid','Due Amount','Status','Actions'],bills.filter(b=>matches({...b,name:name('customers',b.customer)})).map(b=>[esc(b.id),esc(b.customer?name('customers',b.customer):b.walkin||'Walk-in Customer'),esc(number(b.bike)),esc(b.date),money(billTotals(b).total),money(paid(b)),money(due(b)),badge(payStatus(b)),`<div class="rowactions"><button class="btn secondary small" data-invoice="${db.jobs.includes(b)?'jobs':'sales'}|${esc(b.id)}">Statement</button>${due(b)>0?`<button class="btn success small" data-receive="${db.jobs.includes(b)?'jobs':'sales'}|${esc(b.id)}">Receive</button>`:''}</div>`])))}
function reportPage(){let key=page.slice(7);let bills=[...db.jobs,...db.sales].filter(b=>b.status!=='Cancelled');let range=x=>(!reportFrom||x.date>=reportFrom)&&(!reportTo||x.date<=reportTo);let title='',desc='',headers=[],rows=[],stats=[];if(['sales','purchases','profit'].includes(key)){let purchases=key==='purchases';let source=(purchases?db.purchases:bills).filter(range);let lines=source.flatMap(b=>(b.partLines||[]).map(l=>({...l,bill:b.id,date:b.date,party:purchases?b.supplier:b.customer?name('customers',b.customer):b.walkin||'Walk-in Customer',name:find('parts',l.part)?.name||'Removed part',cost:Number(find('parts',l.part)?.purchase||0)}))).filter(matches);let qty=lines.reduce((s,l)=>s+Number(l.qty),0),revenue=lines.reduce((s,l)=>s+l.qty*l.price,0),profit=lines.reduce((s,l)=>s+l.qty*(l.price-l.cost),0);title=key==='profit'?'Spare Parts Profit Report':`Part-Wise ${purchases?'Purchase':'Sales'} Report`;desc=key==='profit'?'Parts margin before tax and discounts; based on current sample purchase costs.':'Itemized spare parts across '+(purchases?'supplier purchases':'job cards and counter sales');stats=key==='profit'?[['PARTS MARGIN',money(profit)],['PARTS REVENUE',money(revenue)],['MARGIN (%)',revenue?(profit/revenue*100).toFixed(1)+'%':'0%'],['ITEM LINES',lines.length]]:[['TOTAL PARTS QUANTITY',qty],['TOTAL '+(purchases?'PURCHASE COST':'SALES REVENUE'),money(revenue)],['UNIQUE PARTS',new Set(lines.map(l=>l.part)).size],['RECORDS',lines.length]];headers=['Bill ID','Date',purchases?'Supplier':'Customer','Part Name','SKU','Qty',key==='profit'?'Unit Margin':'Unit Price',key==='profit'?'Total Margin':'Total'];rows=lines.map(l=>[esc(l.bill),esc(l.date),esc(l.party),esc(l.name),esc(l.part),l.qty,money(key==='profit'?l.price-l.cost:l.price),money(l.qty*(key==='profit'?l.price-l.cost:l.price))]);}else if(key==='dues'){title='Outstanding Dues Report';desc='Pending customer and supplier balances from sample records.';let outstanding=[...bills.map(b=>({...b,party:b.customer?name('customers',b.customer):b.walkin,type:'Receivable'})),...db.purchases.map(b=>({...b,party:b.supplier,type:'Payable'}))].filter(b=>due(b)>0&&range(b)&&matches(b));stats=[['CUSTOMER DUES',money(bills.reduce((s,b)=>s+due(b),0))],['SUPPLIER DUES',money(db.purchases.reduce((s,b)=>s+due(b),0))],['OUTSTANDING BILLS',outstanding.length],['PARTIES',new Set(outstanding.map(b=>b.party)).size]];headers=['Bill ID','Date','Party','Type','Invoice Total','Paid','Due'];rows=outstanding.map(b=>[esc(b.id),esc(b.date),esc(b.party),badge(b.type),money(billTotals(b).total),money(paid(b)),money(due(b))]);}else{title='Customer Collection Report';desc='Customer advances and later receipts, with no double counting.';let rs=allReceipts().filter(range).filter(matches);let total=rs.reduce((s,r)=>s+Number(r.amount),0);stats=[['TOTAL COLLECTIONS',money(total)],['RECEIPTS',rs.length],['AVERAGE COLLECTION',money(total/Math.max(1,rs.length))],['ACCOUNTS',new Set(rs.map(r=>r.account)).size]];headers=['Txn ID','Date','Customer','Bill ID','Amount','Mode','Account'];rows=rs.map(r=>[esc(r.id),esc(r.date),esc(r.party),esc(r.bill),money(r.amount),esc(r.mode),esc(name('accounts',r.account))]);}return `<div class="intro"><h2>${title}</h2><p>${desc}</p></div>`+summary(stats)+`<div class="toolbar"><input id="search" class="search" placeholder="Search this report…" aria-label="Search report" value="${esc(search)}"><label>From <input type="date" id="reportFrom" value="${esc(reportFrom)}"></label><label>To <input type="date" id="reportTo" value="${esc(reportTo)}"></label><span class="spacer"></span>${btn('Print / Preview','printReport','secondary','print')}${btn('Export Excel','export','success','download')}</div>`+table(headers,rows)}
function appointmentPage(){let tabs=`<div class="tabs">${[['list','All Bookings List'],['matrix','Booking Matrix']].map(([k,t])=>`<button class="tab ${tabState===k?'active':''}" data-tab="${k}">${t}</button>`).join('')}</div>`;if(tabState==='matrix'){let now=new Date(),y=now.getFullYear(),m=now.getMonth(),days=new Date(y,m+1,0).getDate(),offset=(new Date(y,m,1).getDay()+6)%7;return tabs+`<div class="toolbar"><h2>${now.toLocaleString('en',{month:'long',year:'numeric'})}</h2><span class="spacer"></span>${btn('Book Appointment','add','','plus')}</div><div class="calendar">${['MON','TUE','WED','THU','FRI','SAT','SUN'].map(d=>`<div class="dayname">${d}</div>`).join('')}${Array.from({length:offset},()=>'<div></div>').join('')}${Array.from({length:days},(_,i)=>{let date=`${y}-${String(m+1).padStart(2,'0')}-${String(i+1).padStart(2,'0')}`;return `<div>${i+1}<button class="addday" data-bookdate="${date}" aria-label="Book ${date}">+</button>${db.appointments.filter(a=>a.date===date).map(a=>`<div class="event" data-edit="appointments|${esc(a.id)}">${esc(a.slot)}<br>${esc(a.name)}</div>`).join('')}</div>`}).join('')}</div>`}return tabs+summary([['TODAY’S BOOKINGS',db.appointments.filter(a=>a.date===today()).length],['UPCOMING BOOKINGS',db.appointments.filter(a=>a.date>today()).length],['CONVERTED TO JOB CARD',db.appointments.filter(a=>a.job).length],['TOTAL BOOKINGS',db.appointments.length]])+toolbar('Book Appointment')+table(['Booking ID','Date & Slot','Customer','Vehicle','Complaint','Status','Actions'],db.appointments.filter(matches).map(a=>[esc(a.id),`${esc(a.date)}<small>${esc(a.slot)}</small>`,`${esc(a.name)}<small>${esc(a.mobile)}</small>`,esc(a.number),esc(a.complaint),badge(a.status),actions('appointments',a.id,!a.job&&a.status!=='Cancelled'?`<button class="btn success small" data-convert="${esc(a.id)}">Create Job</button>`:a.job?esc(a.job):'')]))}
function auditPage(){return `<div class="intro"><h2>System Audit & Activity Logs</h2><p>Activity recorded in this sample workspace.</p></div>`+summary([['TOTAL ACTIVITY LOGS',db.audit.length],['TODAY’S ACTIVITIES',db.audit.filter(a=>a.date.startsWith(today())).length],['CREATED RECORDS',db.audit.filter(a=>a.action==='Create').length],['UPDATED RECORDS',db.audit.filter(a=>a.action==='Update').length]])+toolbar('')+table(['Date & Time','User / Role','Module','Action','Event Details','Status'],db.audit.filter(matches).map(a=>[esc(new Date(a.date).toLocaleString('en-IN')),esc(a.user)+' / Admin',esc(a.module),badge(a.action),esc(a.detail),badge(a.status)]))}
function settingsPage(){let s=db.settings;return `<div class="intro"><h2>System & Garage Settings</h2><p>Workshop profile, invoice details and ID prefixes.</p></div><form id="settingsForm"><div class="settingsgrid"><section class="panel"><div class="panelhead"><h2>${icon('settings')}Garage Profile & Contact Info</h2></div><div class="panelbody">${field({key:'name',label:'Shop / Garage Name',required:true},s)}${field({key:'phone',label:'Contact Mobile / Phone'},s)}${field({key:'email',label:'Email Address',type:'email'},s)}${field({key:'gst',label:'GSTIN Number'},s)}${field({key:'state',label:'State & State Code'},s)}${field({key:'address',label:'Full Address (Printed on Invoices)',type:'textarea'},s)}</div></section><section class="panel"><div class="panelhead"><h2>${icon('file')}Invoice & System Settings</h2></div><div class="panelbody"><div class="notice">Sample tax is 0%. Production billing treatment must be confirmed before real invoices are issued.</div>${field({key:'footer',label:'Invoice Footer',type:'textarea'},s)}<div class="brandmark" style="background:#0b1120;margin:20px auto"><span>BD</span><small>MOTO CARE</small></div><p style="text-align:center;color:#94a3b8;font-size:11px">Original BIKE DOCTOR identity</p></div></section></div><div class="toolbar" style="margin-top:20px"><button class="btn" type="submit">${icon('check')}Save All Settings</button>${btn('Download Sample Backup','backup','secondary','download')}</div></form><div class="notice">Prototype records stay in this browser. This is not a secure production database. No external messages, bank transfers or customer data imports are connected.</div>`}
function listsPage(){return `<div class="intro"><h2>Dropdown List Management <span class="badge info">Master Control</span></h2><p>Customize the options used in this sample garage.</p></div><div class="listlayout"><div class="listselector">${Object.entries(db.lists).map(([k,v])=>`<button class="${k===listName?'active':''}" data-list="${esc(k)}">${esc(k)} <span style="float:right">${v.length}</span></button>`).join('')}</div><section class="panel"><div class="panelhead"><h2>${esc(listName)}</h2><span class="badge">${db.lists[listName].length} Options</span></div><div class="panelbody"><form id="listForm" class="toolbar"><input name="option" placeholder="Type a new option name…" required aria-label="New dropdown option"><button class="btn" type="submit">+ Add Option</button></form>${db.lists[listName].map((x,i)=>`<div class="listoption"><span>${esc(x)}</span><button class="btn secondary small" data-removeoption="${i}" aria-label="Remove ${esc(x)}">×</button></div>`).join('')}</div></section></div>`}
function attendancePage(){let day=today(),saved=db.attendance[day]||{};return `<div class="tabs"><button class="tab active">Daily Attendance Marking</button><button class="tab" data-page="payroll">Per Job Salary</button></div><div class="notice">${day} · ${db.attendance[day]?'Saved attendance':'Not saved yet — no attendance assumed'}</div><form id="attendanceForm">${table(['Staff ID','Staff Name','Designation','Salary Scheme','Attendance Status','Remarks'],db.staff.map(s=>[esc(s.id),esc(s.name),esc(s.designation),s.salaryType==='Per Job'?esc(s.salary)+'% (Per Job)':money(s.salary)+' '+esc(s.salaryType),`<select name="status-${esc(s.id)}" aria-label="Attendance for ${esc(s.name)}">${opts(['Unmarked','Present','Half Day','Absent'],saved[s.id]?.status||'Unmarked')}</select>`,`<input name="note-${esc(s.id)}" value="${esc(saved[s.id]?.note||'')}" placeholder="Optional note" aria-label="Note for ${esc(s.name)}">`]))}<div class="toolbar" style="margin-top:20px"><button class="btn" type="submit">Save Attendance</button>${btn('Export Excel','export','secondary','download')}</div></form>`}
function payrollPage(){let rows=db.staff.filter(s=>s.salaryType==='Per Job').map(s=>{let jobs=db.jobs.filter(j=>j.mechanic===s.id&&['Completed','Delivered'].includes(j.status)),earned=round(jobs.reduce((a,j)=>a+billTotals(j).labour,0)*Number(s.salary)/100),paidAmount=db.expenses.filter(e=>e.staff===s.id).reduce((a,e)=>a+Number(e.amount),0);return {...s,jobs:jobs.length,earned,paidAmount,balance:earned-paidAmount}});return `<div class="notice">Sample rule: commission is earned on completed/delivered jobs’ labour before tax and discount. Production pay rules still need confirmation.</div>`+summary([['PER JOB STAFF',rows.length],['COMPLETED ASSIGNED JOBS',rows.reduce((s,r)=>s+r.jobs,0)],['TOTAL SALARY EARNED',money(rows.reduce((s,r)=>s+r.earned,0))],['BALANCE DUE',money(rows.reduce((s,r)=>s+r.balance,0))]])+toolbar('')+table(['Mechanic / Staff','Skills','Per Job Rate','Completed Jobs','Earned','Paid','Balance'],rows.filter(matches).map(s=>[esc(s.name),esc(s.skills),esc(s.salary)+'%',s.jobs,money(s.earned),money(s.paidAmount),money(s.balance)]))}
function billPage(key){
  const rows=(db[key]||[]).filter(matches).filter(record=>!filter||record.status===filter);
  if(key==='purchases')return summary([['PURCHASE ENTRIES',db.purchases.length],['PURCHASE VALUE',money(db.purchases.reduce((sum,r)=>sum+billTotals(r).total,0))],['PAID',money(db.purchases.reduce((sum,r)=>sum+Number(r.advance||0),0))],['BALANCE DUE',money(db.purchases.reduce((sum,r)=>sum+due(r),0))]])+toolbar('Add Purchase')+table(['Purchase ID','Date','Vendor','Invoice No.','Total','Paid','Due','Actions'],rows.map(r=>[esc(r.id),esc(r.date),esc(r.supplier),esc(r.invoice||'—'),money(billTotals(r).total),money(paid(r)),money(due(r)),actions(key,r.id)]));
  if(key==='sales')return summary([['SALES INVOICES',db.sales.length],['TOTAL SALES',money(db.sales.reduce((sum,r)=>sum+billTotals(r).total,0))],['PAID',money(db.sales.reduce((sum,r)=>sum+paid(r),0))],['BALANCE DUE',money(db.sales.reduce((sum,r)=>sum+due(r),0))]])+toolbar('Add Sale')+table(['Invoice No.','Date','Customer','Vehicle Number','Parts','Total','Paid','Due','Actions'],rows.map(r=>[esc(r.id),esc(r.date),esc(r.customer?name('customers',r.customer):r.walkin||'Walk-in Customer'),esc(r.bike?number(r.bike):r.vehicleNumber||'—'),(r.partLines||[]).map(line=>esc(line.name||name('parts',line.part))).join('<br>')||'—',money(billTotals(r).total),money(paid(r)),money(due(r)),actions(key,r.id)]));
  return summary([['TOTAL JOB CARDS',rows.length],['PENDING',rows.filter(r=>r.status==='Pending').length],['IN PROGRESS',rows.filter(r=>r.status==='In Progress').length],['COMPLETED',rows.filter(r=>r.status==='Completed').length]])+toolbar('Add Job Card')+table(['Job Card No.','Date','Customer','Vehicle','Work Type','Status','Total','Actions'],rows.map(r=>[esc(r.id),esc(r.date),esc(name('customers',r.customer)),esc(number(r.bike)),esc(r.work),badge(r.status),money(billTotals(r).total),actions(key,r.id)]));
}
let interactionScrollState=null;
function captureInteractionScroll(){return {windowX:window.scrollX,windowY:window.scrollY,nodes:[...document.querySelectorAll('nav,#workspace,#content,main,#content .tablewrap,#content .jobSplit,#content .purchaseItemScroll,#content .attendanceMatrixWrap')].map((node,index)=>({index,scrollLeft:node.scrollLeft,scrollTop:node.scrollTop}))}}
function restoreInteractionScroll(state){if(!state)return;window.scrollTo(state.windowX,state.windowY);if(document.scrollingElement)document.scrollingElement.scrollTop=state.windowY;const nodes=[...document.querySelectorAll('nav,#workspace,#content,main,#content .tablewrap,#content .jobSplit,#content .purchaseItemScroll,#content .attendanceMatrixWrap')];for(const item of state.nodes){if(nodes[item.index]){nodes[item.index].scrollLeft=item.scrollLeft;nodes[item.index].scrollTop=item.scrollTop}}}
document.addEventListener('pointerdown',event=>{if(event.target.closest('#content input,#content select,#content textarea,#content button')){interactionScrollState=captureInteractionScroll();const state=interactionScrollState;setTimeout(()=>restoreInteractionScroll(state),0);setTimeout(()=>restoreInteractionScroll(state),120);setTimeout(()=>restoreInteractionScroll(state),350)}},true);
function render(){
 const renderPage=page;
 const documentScrollTop=interactionScrollState?.windowY??(document.scrollingElement?.scrollTop||0);
 const scrollState=interactionScrollState?.nodes||[...document.querySelectorAll('nav,#workspace,#content,main,#content .tablewrap,#content .jobSplit,#content .purchaseItemScroll,#content .attendanceMatrixWrap')].map((node,index)=>({index,scrollLeft:node.scrollLeft,scrollTop:node.scrollTop}));
 nav();$('#pageTitle').textContent=titles[page]||'Dashboard';$('#crumb').textContent=titles[page]||'Dashboard';let html=page==='dashboard'?dashboard():page==='bikes'?bikesPage():['jobs','sales','purchases'].includes(page)?billPage(page):page==='payments'?paymentsPage():page.startsWith('report-')?reportPage():page==='appointments'?appointmentPage():page==='settings'?settingsPage():page==='lists'?listsPage():page==='audit'?auditPage():page==='attendance'?attendancePage():page==='payroll'?payrollPage():basicPage(page);$('#content').innerHTML=html||dashboard();bindPage();
 const restore=()=>{if(page!==renderPage)return;restoreInteractionScroll({windowX:0,windowY:documentScrollTop,nodes:scrollState})};
 restore();requestAnimationFrame(restore);setTimeout(restore,0);setTimeout(restore,100);setTimeout(restore,300);interactionScrollState=null;
}
function field(f,obj={}){let purchaseLinked=f.key==='purchaseDate'&&latestPartPurchaseDate(obj.id);let value=f.key==='purchaseDate'?partPurchaseDate(obj):(obj[f.key]??f.default??'');let req=f.required?'required':'';let content=f.type==='select'?`<select name="${f.key}" ${req}>${f.placeholder!==false?'<option value="">-- Select --</option>':''}${opts(typeof f.options==='function'?f.options():f.options||[],value)}</select>`:f.type==='textarea'?`<textarea name="${f.key}" ${req}>${esc(value)}</textarea>`:`<input name="${f.key}" type="${f.type||'text'}" value="${esc(value)}" ${req} ${f.readonly?'readonly':''} ${purchaseLinked?'disabled title="From latest saved purchase entry"':''} ${f.type==='number'?'min="0" step="'+(f.integer?'1':'0.01')+'"':''} ${f.type==='tel'?'inputmode="tel"':''}>`;return `<label class="field ${f.full?'full':''}"><span>${esc(f.label)} ${f.required?'<b class="required">*</b>':''}</span>${content}${purchaseLinked?'<small>From the latest purchase entry. Change its date in Purchases.</small>':''}</label>`}
const reference=(key,label='name',includeInactive=false)=>db[key].filter(x=>key!=='accounts'||includeInactive||x.status!=='Inactive').map(x=>({value:x.id,label:key==='customers'?x[label]+(x.mobile?' — '+x.mobile:''):x[label]}));
