const section=t=>({section:t});
const schemas={customers:[section('BASIC & CONTACT INFORMATION'),{key:'id',label:'Customer ID (Auto)',readonly:true},{key:'name',label:'Customer Name',required:true},{key:'mobile',label:'Mobile Number',type:'tel',required:true},{key:'alt',label:'Alternate Mobile',type:'tel'},{key:'type',label:'Customer Type',type:'select',options:list('Customer Types'),default:'Regular'},{key:'email',label:'Email ID',type:'email'},{key:'dob',label:'Date of Birth (Optional)',type:'date'},{key:'gst',label:'GST Number (Optional)'},section('ADDRESS INFORMATION'),{key:'address',label:'Address Details',full:true},{key:'city',label:'City'},{key:'state',label:'State'},{key:'pin',label:'PIN Code'}],bikes:[section('CUSTOMER INFORMATION'),{key:'customer',label:'Customer Name',type:'select',options:()=>reference('customers'),required:true},{key:'id',label:'Vehicle ID (Auto)',readonly:true},section('VEHICLE DETAILS & SPECIFICATIONS'),{key:'number',label:'Vehicle Number',required:true},{key:'type',label:'Vehicle Type',type:'select',options:list('Vehicle Types'),required:true},{key:'brand',label:'Vehicle Brand',type:'select',options:list('Vehicle Brands'),required:true},{key:'model',label:'Vehicle Model',required:true},{key:'variant',label:'Variant (Optional)'},{key:'year',label:'Manufacturing Year',type:'number'},{key:'registration',label:'Registration Date',type:'date'},{key:'fuel',label:'Fuel Type',type:'select',options:list('Fuel Types'),default:'Petrol'},{key:'transmission',label:'Transmission',type:'select',options:list('Transmission Types'),default:'Manual'},{key:'chassis',label:'Chassis Number'},{key:'engine',label:'Engine Number'},{key:'vin',label:'VIN Number (Optional)'}],services:[{key:'id',label:'Service ID',readonly:true},{key:'name',label:'Service Name',required:true},{key:'category',label:'Category',type:'select',options:list('Service Categories'),default:'General Service'},{key:'charge',label:'Standard Labour Charge (₹)',type:'number',required:true},{key:'status',label:'Status',type:'select',options:['Active','Inactive'],default:'Active'},{key:'description',label:'Service Description / Notes',type:'textarea',full:true}],staff:[section('PERSONAL & CONTACT DETAILS'),{key:'id',label:'Staff ID (Auto)',readonly:true},{key:'name',label:'Staff Name',required:true},{key:'mobile',label:'Mobile Number',required:true,type:'tel'},{key:'designation',label:'Designation',required:true,type:'select',options:list('Staff Designations'),default:'Mechanic'},{key:'skills',label:'Specialization / Skills',type:'select',options:list('Mechanic Specializations')},{key:'experience',label:'Experience (Years)',type:'number'},{key:'address',label:'Address Details',full:true},section('IDENTITY DETAILS (OPTIONAL)'),{key:'aadhaar',label:'Aadhaar Number'},{key:'drivingLicense',label:'Driving Licence Number'},section('WORK & REMUNERATION'),{key:'joining',label:'Joining Date',type:'date'},{key:'salaryType',label:'Salary Type',type:'select',options:['Monthly','Daily','Per Job'],default:'Per Job'},{key:'salary',label:'Salary Amount / Per Job Percentage',type:'number'},{key:'status',label:'Status',type:'select',options:['Active','Inactive'],default:'Active'},{key:'emergency',label:'Emergency Contact'},{key:'remarks',label:'Remarks'}],parts:[section('BASIC INFORMATION & CLASSIFICATION'),{key:'id',label:'Part Code / SKU',required:true},{key:'name',label:'Part Name',required:true},{key:'hsn',label:'HSN / SAC Code'},{key:'category',label:'Category',type:'select',options:list('Spare Part Categories'),required:true},{key:'brand',label:'Brand'},{key:'preferredVendor',label:'Preferred Vendor',type:'select',options:()=>[...new Set((db.purchases||[]).filter(p=>p.status!=='Cancelled').map(p=>String(p.supplier||'').trim()).filter(Boolean))].sort((a,b)=>a.localeCompare(b))},{key:'unit',label:'Unit',type:'select',options:list('Part Units (UOM)'),default:'PCS'},{key:'rack',label:'Rack / Shelf No.'},section('PRICING & INVENTORY LEVELS'),{key:'purchase',label:'Purchase Price (₹)',type:'number',required:true},{key:'price',label:'Selling Price (₹)',type:'number',required:true},{key:'gst',label:'GST (%)',type:'select',options:[0,5,12,18,28],default:0},{key:'opening',label:'Opening Stock',type:'number',required:true,default:0},{key:'min',label:'Min Stock Alert',type:'number',required:true,default:5},{key:'notes',label:'Remarks / Notes',full:true}],accounts:[{key:'id',label:'Account Code',readonly:true},{key:'name',label:'Account Name / Label',required:true},{key:'type',label:'Account Type',type:'select',options:['Cash in Hand','Bank Current Account','Bank Savings Account','UPI / Digital Wallet','Petty Cash','Other'],required:true},{key:'opening',label:'Opening Balance (₹)',type:'number',default:0},{key:'status',label:'Status',type:'select',options:['Active','Inactive'],default:'Active'},{key:'description',label:'Remarks / Description',type:'textarea',full:true}],insurance:[section('VEHICLE & CUSTOMER INFORMATION'),{key:'id',label:'Policy Record ID',readonly:true},{key:'bike',label:'Vehicle Number',type:'select',options:()=>reference('bikes','number'),required:true},section('INSURANCE DATES & POLICY DETAILS'),{key:'issue',label:'Insurance Issue Date',type:'date',required:true,default:today()},{key:'expiry',label:'Policy Expiry Date',type:'date',required:true},{key:'provider',label:'Insurance Company Name',required:true},{key:'policy',label:'Policy Number / Cover Note'},{key:'premium',label:'Premium Amount (₹)',type:'number'},{key:'notes',label:'Notes / Remarks',full:true}],expenses:[{key:'id',label:'Expense ID',readonly:true},{key:'category',label:'Category',type:'select',options:list('Expense Categories'),required:true},{key:'amount',label:'Amount (₹)',type:'number',required:true},{key:'date',label:'Date',type:'date',required:true,default:today()},{key:'mode',label:'Payment Mode',type:'select',options:list('Payment Modes'),default:'Cash',required:true},{key:'account',label:'Paid From Account',type:'select',options:()=>reference('accounts'),required:true},{key:'staff',label:'Staff (For Salary / Advance)',type:'select',options:()=>reference('staff')},{key:'description',label:'Description',type:'textarea',full:true}],appointments:[section('BOOKING SCHEDULE'),{key:'id',label:'Booking ID (Auto)',readonly:true},{key:'date',label:'Appointment Date',type:'date',required:true,default:today()},{key:'slot',label:'Preferred Time Slot',type:'select',options:['09:00 AM - 10:00 AM','10:00 AM - 11:00 AM','11:00 AM - 12:00 PM','12:00 PM - 01:00 PM','02:00 PM - 03:00 PM','03:00 PM - 04:00 PM','04:00 PM - 05:00 PM','05:00 PM - 06:00 PM'],required:true},{key:'status',label:'Booking Status',type:'select',options:['Confirmed','In Progress','Completed','Cancelled'],default:'Confirmed'},section('CUSTOMER & VEHICLE INFORMATION'),{key:'name',label:'Customer Full Name',required:true},{key:'mobile',label:'Mobile Number',type:'tel',required:true},{key:'number',label:'Vehicle Registration Number',required:true},{key:'brand',label:'Vehicle Brand / Make'},{key:'model',label:'Vehicle Model'},{key:'complaint',label:'Customer Complaint / Work Requested',type:'textarea',required:true,full:true},{key:'notes',label:'Internal Remarks / Notes',full:true}],users:[{key:'name',label:'Full Name',required:true},{key:'username',label:'Login User ID / Username',required:true},{key:'role',label:'Role',type:'select',options:['Admin','Manager','Mechanic','User'],default:'User'}]};
function openModal(title,html){lastFocus=document.activeElement;$('#modalTitle').textContent=title;$('#modalBody').innerHTML=html;$('#modal').hidden=false;document.body.style.overflow='hidden';setTimeout(()=>$('#modalBody input:not([readonly]),#modalBody select,#closeModal')?.focus(),20)}
function closeModal(){let wasOpen=!$('#modal').hidden;$('#modal').hidden=true;$('#modalBody').innerHTML='';document.body.style.overflow='';jobDraft=null;if(wasOpen&&lastFocus?.isConnected)lastFocus.focus()}
function editRecord(key,id,initial={}){if(['jobs','sales','purchases'].includes(key)){billForm(key,id,initial);return}editing={key,id};let record=id?find(key,id):{id:nextId(key),...initial};if(!record)return;let title=(id?'Edit ':'Add New ')+({customers:'Customer',bikes:'Vehicle',services:'Service',staff:'Staff',parts:'Spare Part',accounts:'Payment Account',insurance:'Insurance Policy',expenses:'Expense',appointments:'Appointment',users:'User'}[key]);let html=`<form id="recordForm"><div class="formbody">${key==='users'?'<div class="notice">Sample user record only. No real login credentials are requested or created.</div>':''}<div class="formgrid">${schemas[key].map(f=>f.section?`<div class="formsection">${f.section}</div>`:field(f,record)).join('')}</div></div><div class="formactions">${btn('Cancel','cancel','secondary')}<button class="btn" type="submit">${icon('check')}Save ${title.replace(/^(Edit|Add New) /,'')}</button></div></form>`;openModal(title,html);$('#recordForm').onsubmit=e=>{e.preventDefault();let data=Object.fromEntries(new FormData(e.target));for(let f of schemas[key])if(f.type==='number')data[f.key]=Number(data[f.key]||0);if(db[key].some(x=>x.id===data.id&&x.id!==id))return toast('This ID already exists. Choose a unique ID.');if(key==='bikes'){data.number=data.number.trim().toUpperCase();if(db.bikes.some(x=>x.number===data.number&&x.id!==id))return toast('This vehicle number already exists.')}if(key==='insurance'&&data.expiry<data.issue)return toast('Expiry date must be on or after the issue date.');if(key==='staff'&&data.salaryType==='Per Job'&&data.salary>100)return toast('Per job percentage must be between 0 and 100.');if(key==='expenses'&&data.amount<=0)return toast('Enter an amount greater than zero.');if(key==='users'&&db.users.some(u=>u.username===data.username&&u.id!==id))return toast('This username already exists.');if(key==='parts'&&stock(id||data.id)-Number(record.opening||0)+Number(data.opening)<0)return toast('Opening stock cannot make the balance negative.');if(id)db[key][db[key].findIndex(x=>x.id===id)]={...record,...data};else db[key].push(data);audit(id?'Update':'Create',`${data.id} saved`);save('Saved in this sample workspace');closeModal();render()}}
function billForm(key,id,initial={}){let record=id?structuredClone(find(key,id)):{id:nextId(key),date:today(),status:key==='jobs'?'Pending':'Completed',invoiceType:db.settings.defaultInvoiceType||'gst',tax:0,discount:0,advance:0,account:db.accounts.find(a=>a.status!=='Inactive')?.id,mode:'Cash',serviceLines:[],partLines:[],...initial};jobDraft={key,id,record};let isJob=key==='jobs',isPur=key==='purchases';let fields=[section(isPur?'PURCHASE INFORMATION':'BASIC INFORMATION'),...(!isPur?[{key:'invoiceType',label:'Invoice Type',type:'select',options:[{value:'gst',label:'GST Invoice'},{value:'non-gst',label:'Non-GST Invoice'}],default:record.invoiceType||(Number(billTotals(record).tax)>0?'gst':'non-gst')}]:[]),{key:'id',label:isJob?'Job Card No. (Auto)':isPur?'Purchase ID (Auto)':'Invoice / Bill No.',readonly:true},{key:'date',label:isJob?'Job Date':'Date',type:'date',required:true}];if(isPur)fields.push({key:'supplier',label:'Supplier / Vendor',required:true},{key:'invoice',label:'Supplier Invoice / Bill No.',required:true});else fields.push({key:'customer',label:'Registered Customer',type:'select',options:()=>reference('customers'),required:isJob},...(isJob?[{key:'bike',label:'Vehicle Number',type:'select',options:()=>db.bikes.filter(b=>!record.customer||b.customer===record.customer).map(b=>({value:b.id,label:b.number})),required:true},{key:'odometer',label:'Odometer (Kms)',type:'number'},{key:'work',label:'Work Type',type:'select',options:list('Work Types'),required:true},{key:'status',label:'Job Status',type:'select',options:list('Job Card Statuses'),default:'Pending'},{key:'mechanic',label:'Assigned Mechanic',type:'select',options:()=>reference('staff')},{key:'delivery',label:'Expected Delivery Date',type:'date'},{key:'complaint',label:'Customer Complaint',type:'textarea',full:true}]:[{key:'walkin',label:'Walk-in Customer Name (If Unregistered)',default:'Walk-in Customer'}]));fields.push({key:'notes',label:'Notes / Special Instructions',full:true});openModal(isJob?(id?'Edit Job Card':'Add New Job Card'):isPur?'Purchase Entry':'Spare Part Counter Sale & Invoice',`<form id="billForm"><div class="formbody"><div class="notice">Prototype transaction. Stock is reserved on job save and restored if cancelled. No real money is transferred.</div><div class="formgrid">${fields.map(f=>f.section?`<div class="formsection">${f.section}</div>`:field(f,record)).join('')}</div>${isJob?'<div class="jobLinesScroll jobServiceScroller">':''}${isJob?`<div class="lineheading">ASSIGNED SERVICES / LABOUR ${btn('Add Service','addService','secondary small','plus')}</div><div class="notice">Edit each service charge, part rate, or line discount for this job only. These changes do not change Service Master or Spare Parts Master prices.</div><div id="serviceLines"></div>`:''}${isJob?'</div>':''}${isJob?'<div class="jobLinesScroll jobPartScroller">':''}<div class="lineheading">${isPur?'PURCHASE PARTS ITEMS':'SPARE PARTS '+(isJob?'USED':'TO SELL')} ${btn('Add Part','addPart','secondary small','plus')}</div><div id="partLines"></div>${isJob?'</div>':''}${isJob?'<div class="jobBillingPanel">':''}<div class="formsection" style="margin-top:24px">BILLING & PAYMENT SUMMARY</div><div class="${isJob?'jobPaymentFields':'formgrid'}">${field({key:'mode',label:'Payment Mode',type:'select',options:list('Payment Modes')},record)}${field({key:'account',label:isPur?'Paid From Account':'Deposit Account',type:'select',options:()=>reference('accounts','name',!!id),required:true},record)}</div><div class="totals ${isJob?'jobBillingTotals':''}"><div><span>Labour / Service</span><b id="sumLabour"></b></div><div><span>Parts</span><b id="sumParts"></b></div>${isJob?'':`<div><label for="discount">Discount (₹)</label><input id="discount" name="discount" type="number" min="0" step=".01" value="${record.discount||0}"></div>`}<div><span>Total GST</span><b id="sumTax"></b></div><div class="grand"><span>Grand Total</span><b id="sumTotal"></b></div><div><label for="advance">${isPur?'Paid Amount':'Advance / Paid'} (₹)</label><input id="advance" name="advance" type="number" inputmode="decimal" min="0" step="0.01" aria-label="Advance or paid amount" value="${record.advance||0}"></div><div><span>Later receipts</span><b>${money(id?paid(record)-Number(record.advance||0):0)}</b></div><div><span>Due Amount</span><b id="sumDue"></b></div></div>${isJob?'</div>':''}</div><div class="formactions">${btn('Cancel','cancel','secondary')}<button type="submit" class="btn">${icon('check')}Save ${isJob?'Job Card':isPur?'Purchase Entry':'Sale'}</button></div></form>`);lineRender();if(isJob)$('#billForm [name="customer"]').onchange=e=>{let select=$('#billForm [name="bike"]');select.innerHTML='<option value="">-- Select Vehicle --</option>'+opts(db.bikes.filter(b=>b.customer===e.target.value).map(b=>({value:b.id,label:b.number})),null)};let invoiceTypeSelect=$('#billForm [name="invoiceType"]');if(invoiceTypeSelect)invoiceTypeSelect.onchange=()=>updateBillTotals();$('#billForm').oninput=e=>{let d=e.target.dataset,b=jobDraft?.record;if(d?.partfield){let [i,key]=d.partfield.split('|');b.partLines[i][key]=Number(e.target.value||0)}else if(d?.charge!==undefined){b.serviceLines[Number(d.charge)].charge=Number(e.target.value||0)}updateBillTotals()};$('#billForm').onsubmit=saveBill;}
function lineRender(){let b=jobDraft.record,isPur=jobDraft.key==='purchases',isJob=jobDraft.key==='jobs';if($('#serviceLines'))$('#serviceLines').innerHTML=table(['Service / Task',isJob?'Charge for This Job (₹)':'Charge (₹)',''],b.serviceLines.map((l,i)=>[`<select data-line="service|${i}" aria-label="Service ${i+1}"><option value="">-- Select Service --</option>${opts(reference('services'),l.service)}</select>`,`<input type="text" inputmode="decimal" autocomplete="off" data-charge="${i}" aria-label="Service charge for this job ${i+1}" title="Saved on this job only; the Service Master charge stays unchanged." value="${Number(l.charge||0)}">`,`<button type="button" class="btn danger small" data-removeline="service|${i}" aria-label="Remove service">×</button>`]));$('#partLines').innerHTML=table(['Part Name','Stock','Qty',isJob?'Part Rate (₹)':isPur?'Purchase Rate (₹)':'Sale Rate (₹)','GST (%)','Amount',''],b.partLines.map((l,i)=>[`<select data-line="part|${i}" aria-label="Part ${i+1}"><option value="">-- Select Part --</option>${opts(partOptions(),l.part)}</select>`,l.part?(isPur&&b.stockLocation==='godown'&&typeof locationStock==='function'?locationStock(l.part,'godown',jobDraft.id):stock(l.part,jobDraft.id)):'—',`<input type="number" min="0.01" step=".01" value="${l.qty||1}" data-partfield="${i}|qty" aria-label="Quantity ${i+1}">`,`<input type="text" inputmode="decimal" autocomplete="off" value="${l.price||0}" data-partfield="${i}|price" aria-label="${isJob?'Part rate for this job':'Part rate'} ${i+1}" title="${isJob?'Saved on this job only; the Spare Parts Master rate stays unchanged.':'Transaction rate for this entry.'}">`,`<select data-partfield="${i}|gst" aria-label="Part GST ${i+1}">${opts([0,5,12,18,28],l.gst||0)}</select>`,`<span id="lineAmount${i}">${money(Number(l.qty)*Number(l.price)*(1+Number(l.gst||0)/100))}</span>`,`<button type="button" class="btn danger small" data-removeline="part|${i}" aria-label="Remove part">×</button>`]));updateBillTotals()}
function updateBillTotals(){if(!jobDraft)return;let b=jobDraft.record;let discountField=$('#discount');if(discountField)b.discount=Number(discountField.value||0);b.advance=Number($('#advance')?.value||0);let labourTaxField=$('#labourTax');if(labourTaxField)b.tax=Number(labourTaxField.value||0);let t=billTotals(b);$('#sumLabour').textContent=money(t.labour);$('#sumParts').textContent=money(t.parts);$('#sumTax').textContent=money(t.tax);$('#sumTotal').textContent=money(t.total);let later=jobDraft.id?db.receipts.filter(r=>r.bill===jobDraft.id).reduce((s,r)=>s+Number(r.amount),0):0;let pending=Math.max(0,round(t.total-b.advance-later));$('#sumDue').textContent=money(pending);let pendingDisplay=$('#currentJobPendingDue');if(pendingDisplay)pendingDisplay.textContent=money(pending);b.partLines.forEach((l,i)=>{let e=$('#lineAmount'+i);if(e)e.textContent=money(l.qty*l.price*(1+Number(l.gst||0)/100))})}
function saveBill(e){e.preventDefault();let {key,id,record}=jobDraft,data={...record,...Object.fromEntries(new FormData(e.target))};data.advance=Number(data.advance||0);data.discount=Number(data.discount||0);data.tax=Number(data.tax||0);if(!Number.isFinite(data.advance)||data.advance<0)return toast('Enter a valid advance or paid amount.');/* Snapshot transaction line values; never write them back to master records. */data.serviceLines=structuredClone(record.serviceLines);data.partLines=structuredClone(record.partLines);let t=billTotals(data);if(data.serviceLines.some(l=>!l.service||!Number.isFinite(Number(l.charge))||Number(l.charge)<0)||data.partLines.some(l=>!l.part||!Number.isInteger(Number(l.qty))||Number(l.qty)<=0||!Number.isFinite(Number(l.price))||Number(l.price)<0))return toast('Complete each service and part line.');if(!data.serviceLines.length&&!data.partLines.length)return toast('Add at least one service or part.');if(data.discount>t.labour+t.parts)return toast('Discount cannot exceed the subtotal.');let later=id?db.receipts.filter(r=>r.bill===id).reduce((s,r)=>s+Number(r.amount),0):0;if(data.advance+later>t.total)return toast('Payments cannot exceed the bill total.');if(key!=='purchases'&&data.status!=='Cancelled'){let used={};for(let l of data.partLines)used[l.part]=(used[l.part]||0)+Number(l.qty);for(let [part,qty]of Object.entries(used))if(qty>stock(part,id))return toast(`Not enough stock for ${name('parts',part)}. Available: ${stock(part,id)}.`)}if(data.status==='Cancelled'&&(data.advance||later))return toast('A paid job needs a reversal workflow before cancellation.');if(key==='jobs'&&find('bikes',data.bike)?.customer!==data.customer)return toast('Select a bike belonging to this customer.');if(id)db[key][db[key].findIndex(b=>b.id===id)]=data;else db[key].push(data);audit(id?'Update':'Create',`${data.id} saved`);save('Transaction saved in this sample workspace');closeModal();render()}
function receive(key,id){let bill=find(key,id);openModal('Collect Customer Payment Receipt',`<form id="receiveForm"><div class="formbody"><div class="notice">Records a sample receipt only. No bank transfer or payment request is sent.</div><div class="formgrid">${field({key:'bill',label:'Job Card / Bill ID',readonly:true},{bill:id})}${field({key:'due',label:'Current Pending Due (₹)',readonly:true},{due:due(bill).toFixed(2)})}${field({key:'amount',label:'Amount Received (₹)',type:'number',required:true},{amount:due(bill)})}${field({key:'date',label:'Payment Date',type:'date',required:true},{date:today()})}${field({key:'mode',label:'Payment Mode',type:'select',options:list('Payment Modes'),required:true},{mode:'Cash'})}${field({key:'account',label:'Deposit Account',type:'select',options:()=>reference('accounts'),required:true},{account:db.accounts.find(a=>a.status!=='Inactive')?.id})}${field({key:'ref',label:'Reference / Transaction No. (Optional)'})}${field({key:'remarks',label:'Notes / Remarks'})}</div></div><div class="formactions">${btn('Cancel','cancel','secondary')}<button class="btn" type="submit">Record Sample Payment</button></div></form>`);$('#receiveForm').onsubmit=e=>{e.preventDefault();let r=Object.fromEntries(new FormData(e.target));r.amount=Number(r.amount);if(r.amount<=0||r.amount>due(bill))return toast('Enter an amount greater than zero and no more than the pending due.');r.id=nextId('receipts');db.receipts.push(r);audit('Create',`Receipt ${r.id} for ${id}`);save('Sample receipt recorded');closeModal();render()}}
function invoice(key,id){let b=find(key,id),t=billTotals(b),c=find('customers',b.customer),lines=[...(b.serviceLines||[]).map(l=>({name:name('services',l.service),qty:1,rate:l.charge,tax:Number(b.tax||0)})),...(b.partLines||[]).map(l=>({name:name('parts',l.part),qty:l.qty,rate:l.price,tax:l.gst||0}))];openModal('Invoice / Account Statement',`<div class="invoice"><div class="invoicebrand"><div><h2>${esc(db.settings.name)}</h2><strong>GARAGE MANAGEMENT SYSTEM</strong><p>${esc(db.settings.address||'Sample garage · demonstration invoice')}<br>${esc(db.settings.phone)}</p></div><div style="text-align:right"><span class="badge info">SAMPLE INVOICE</span><h3>${esc(id)}</h3><p>Date: ${esc(b.date)}</p></div></div><div class="invoiceinfo"><div><small>BILL TO</small><br><strong>${esc(c?.name||b.walkin||'Walk-in Customer')}</strong><br>${esc(c?.mobile||'')}<br>${esc(c?.address||'')}</div><div><small>VEHICLE</small><br><strong>${esc(number(b.bike))}</strong><br>${esc(b.work||'Counter Sale')}<br>${esc(b.status||'Completed')}</div></div>${table(['Description','Qty','Rate','GST','Amount'],lines.map(l=>[esc(l.name),l.qty,money(l.rate),Number(l.tax)+'%',money(l.qty*l.rate*(1+Number(l.tax)/100))]))}<div class="invoicetotal"><p><span>Subtotal</span><b>${money(t.labour+t.parts)}</b></p><p><span>Discount</span><b>− ${money(b.discount)}</b></p><p><span>GST</span><b>${money(t.tax)}</b></p><p class="grand"><span>Total</span><span>${money(t.total)}</span></p><p><span>Paid</span><b>${money(paid(b))}</b></p><p><span>Outstanding Due</span><b>${money(due(b))}</b></p></div><p style="border-top:1px solid #e2e8f0;padding-top:20px;color:#64748b;font-size:11px">${esc(db.settings.footer)}<br>This is a prototype sample, not a finalized tax invoice.</p></div><div class="formactions">${btn('Close','cancel','secondary')}${btn('Print / Save PDF','print','','print')}</div>`)}
function ledger(id){let entries=[];for(let r of allReceipts())if(r.account===id)entries.push([esc(r.date),'Receipt',esc(r.bill),money(r.amount),'—']);for(let p of db.purchases)if(p.account===id&&p.advance)entries.push([esc(p.date),'Purchase',esc(p.id),'—',money(p.advance)]);for(let e of db.expenses)if(e.account===id)entries.push([esc(e.date),'Expense',esc(e.id),'—',money(e.amount)]);openModal('Account Statement — '+name('accounts',id),`<div class="formbody">${summary([['OPENING',money(find('accounts',id).opening)],['CURRENT BALANCE',money(accountBalance(id))]])}${table(['Date','Type','Reference','Money In','Money Out'],entries)}</div><div class="formactions">${btn('Close','cancel','secondary')}</div>`)}
function accountReferenceCount(id){return db.jobs.concat(db.sales,db.receipts,db.purchases,db.expenses).filter(r=>r.account===id).length}
function deletionLinkedRecords(key,id){
  const links=[];
  const add=(module,match,label)=>{for(const record of db[module]||[])if(match(record))links.push({module,id:record.id,label,detail:record.number||record.name||record.description||''})};
  if(key==='customers'){add('bikes',r=>r.customer===id,'Vehicle');add('jobs',r=>r.customer===id,'Job Card');add('sales',r=>r.customer===id,'Spare Parts Sale');add('insurance',r=>r.customer===id,'Insurance')}
  if(key==='bikes'){add('jobs',r=>r.bike===id,'Job Card');add('insurance',r=>r.bike===id,'Insurance')}
  if(key==='parts')for(const module of ['jobs','sales','purchases'])add(module,r=>r.partLines?.some(line=>line.part===id),{jobs:'Job Card',sales:'Spare Parts Sale',purchases:'Purchase'}[module]);
  if(key==='services')add('jobs',r=>r.serviceLines?.some(line=>line.service===id),'Job Card');
  if(key==='staff')add('jobs',r=>r.mechanic===id,'Job Card');
  if(key==='appointments')add('jobs',r=>r.id===find('appointments',id)?.job,'Job Card');
  if(key==='jobs'){add('receipts',r=>r.bill===id,'Payment Receipt');add('appointments',r=>r.job===id,'Appointment')}
  return links;
}
function showDeletionLinkedRecords(key,id,links){
  const record=find(key,id);
  openModal('Linked Records — Delete These First',`<div class="formbody"><p><strong>${esc(record?.name||record?.number||id)}</strong> is linked to ${links.length} record(s). Open and review each entry, then delete it individually using its normal Delete action.</p><div class="tablewrap"><table><thead><tr><th>Module</th><th>Record ID</th><th>Details</th><th>Action</th></tr></thead><tbody>${links.map((link,index)=>`<tr><td>${esc(link.label)}</td><td>${esc(link.id)}</td><td>${esc(link.detail)}</td><td><button type="button" class="btn secondary small" data-open-deletion-link="${index}">Open Record</button></td></tr>`).join('')}</tbody></table></div><p>Return to this record and try Delete again after removing its links. Records with payment history may require payment reversal first. Nothing is deleted automatically.</p></div><div class="formactions">${btn('Close','cancel','secondary')}</div>`);
  for(const button of document.querySelectorAll('[data-open-deletion-link]'))button.onclick=event=>{
    event.preventDefault();event.stopPropagation();
    const link=links[Number(button.dataset.openDeletionLink)];
    if(!link)return;
    closeModal();go(link.module==='receipts'?'payments':link.module);search=link.id;render();
  };
}
function deleteRecord(key,id){
  const linked=deletionLinkedRecords(key,id);
  if(linked.length){showDeletionLinkedRecords(key,id,linked);return;}
  if(key==='jobs'&&Number(find('jobs',id)?.advance||0)>0)return toast('This Job Card has an advance payment. Reverse the payment through the normal payment workflow before deleting it.');
  const account=find('accounts',id);
  const accountReferences=key==='accounts'?accountReferenceCount(id):0;
  if(key==='accounts'&&accountReferences>0){
    if(account.status==='Inactive')return toast('This account is already inactive. Edit it to reactivate.');
    openModal('Mark Linked Account Inactive',`<div class="formbody"><p><strong>${esc(account.name)}</strong> is linked to ${accountReferences} financial record${accountReferences===1?'':'s'}.</p><p>Marking it inactive preserves transaction history and keeps it out of new account choices. You can reactivate it later by editing the account.</p></div><div class="formactions">${btn('Cancel','cancel','secondary')}${btn('Mark Inactive','confirmDelete','danger')}</div>`);
    $('#modalBody [data-action="confirmDelete"]').onclick=()=>{account.status='Inactive';audit('Update',`${id} marked inactive; linked transaction history preserved`);save('Account marked inactive; linked records preserved');closeModal();render()};
    return;
  }
  const dependencies=key==='customers'?db.bikes.some(b=>b.customer===id)||[...db.jobs,...db.sales].some(b=>b.customer===id):key==='bikes'?db.jobs.some(j=>j.bike===id)||db.insurance.some(i=>i.bike===id):key==='parts'?[...db.jobs,...db.sales,...db.purchases].some(b=>b.partLines?.some(l=>l.part===id)):key==='services'?db.jobs.some(b=>b.serviceLines?.some(l=>l.service===id)):key==='accounts'?false:key==='staff'?db.jobs.some(j=>j.mechanic===id):key==='users'?id==='BD-USR-1001':key==='appointments'?!!find(key,id)?.job:false;
  if(dependencies)return toast('This record is linked to other records and cannot be deleted.');
  openModal('Delete Record',`<div class="formbody"><p>Delete <strong>${esc(id)}</strong> ?</p><p style="color:#64748b">Linked records must be removed first. Supported cloud records can be recovered from Recycle Bin.</p></div><div class="formactions">${btn('Cancel','cancel','secondary')}${btn('Delete Record','confirmDelete','danger')}</div>`);
  $('#modalBody [data-action="confirmDelete"]').onclick=()=>{db[key]=db[key].filter(x=>x.id!==id);audit('Delete',`${id} removed`);save('Sample record deleted');closeModal();render()};
}function exportTable(){let t=$('#content table');if(!t)return toast('Open a table view to export records.');let csv=[...t.rows].map(row=>[...row.cells].filter((_,i)=>!['actions',''].includes(t.rows[0].cells[i]?.innerText.trim().toLowerCase())).map(c=>'"'+c.innerText.replace(/"/g,'""')+'"').join(',')).join('\r\n');download('\ufeff'+csv,`bike-doctor-${page}-${today()}.csv`,'text/csv;charset=utf-8');toast('Excel-compatible CSV exported')}
function download(text,filename,type){let url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function convertAppointment(id){let a=find('appointments',id);if(a.job)return toast('This appointment already has a job.');let c=db.customers.find(c=>c.mobile===a.mobile),b=db.bikes.find(b=>b.number===a.number);if(!c||!b||b.customer!==c.id)return toast('First add this customer and their bike in the master records, then convert the booking.');go('jobs');billForm('jobs',null,{customer:c.id,bike:b.id,complaint:a.complaint,appointment:id,work:'General Service'});let form=$('#billForm'),handler=form.onsubmit;form.onsubmit=e=>{let before=db.jobs.length;handler(e);if(db.jobs.length>before){a.job=db.jobs.at(-1).id;a.status='Converted to Job Card';save();render()}}}
function bindPage(){if($('#search')){$('#search').type='search';$('#search').inputMode='search';$('#search').oninput=e=>{let pos=e.target.selectionStart;search=e.target.value;render();$('#search').focus();$('#search').setSelectionRange(pos,pos)}};for(let s of ['#filter','#stockFilter'])if($(s))$(s).onchange=e=>{filter=e.target.value;render()};for(let [id,key]of [['reportFrom','reportFrom'],['reportTo','reportTo']])if($('#'+id))$('#'+id).onchange=e=>{if(key==='reportFrom')reportFrom=e.target.value;else reportTo=e.target.value;render()};if($('#settingsForm'))$('#settingsForm').onsubmit=e=>{e.preventDefault();let data=Object.fromEntries(new FormData(e.target));const nextSettings={...db.settings,...data};delete nextSettings.defaultLabourTax;delete nextSettings.defaultTax;delete nextSettings.defaultPartsTax;db.settings=nextSettings;audit('Update','Garage settings saved');save('Sample settings saved');render()};if($('#listForm'))$('#listForm').onsubmit=e=>{e.preventDefault();let value=new FormData(e.target).get('option').trim();if(!value)return;if(db.lists[listName].some(x=>x.toLowerCase()===value.toLowerCase()))return toast('This option already exists.');db.lists[listName].push(value);audit('Update',`${listName}: added ${value}`);save('Dropdown option added');render()};if($('#attendanceForm'))$('#attendanceForm').onsubmit=e=>{e.preventDefault();let data=new FormData(e.target);db.attendance[today()]=Object.fromEntries(db.staff.map(s=>[s.id,{status:data.get('status-'+s.id),note:data.get('note-'+s.id)}]));audit('Update',`Attendance saved for ${today()}`);save('Sample attendance saved');render()}}
document.addEventListener('click',e=>{let el=e.target.closest('[data-page],[data-new],[data-action],[data-edit],[data-delete],[data-status],[data-tab],[data-list],[data-removeoption],[data-invoice],[data-receive],[data-ledger],[data-removeline],[data-bookdate],[data-convert]');if(!el)return;let d=el.dataset;if(d.page){e.preventDefault();go(d.page)}else if(d.new){go(d.new);editRecord(d.new)}else if(d.edit){editRecord(...d.edit.split('|'))}else if(d.delete){deleteRecord(...d.delete.split('|'))}else if(d.status!==undefined){filter=d.status;render()}else if(d.tab){tabState=d.tab;search='';render()}else if(d.list){listName=d.list;render()}else if(d.removeoption!==undefined){db.lists[listName].splice(Number(d.removeoption),1);audit('Update',`${listName}: removed option`);save('Dropdown option removed');render()}else if(d.invoice)invoice(...d.invoice.split('|'));else if(d.receive)receive(...d.receive.split('|'));else if(d.ledger)ledger(d.ledger);else if(d.bookdate)editRecord('appointments',null,{date:d.bookdate});else if(d.convert)convertAppointment(d.convert);else if(d.removeline){let [kind,i]=d.removeline.split('|');jobDraft.record[kind==='service'?'serviceLines':'partLines'].splice(Number(i),1);lineRender()}else if(d.action==='add')editRecord(page);else if(d.action==='cancel')closeModal();else if(d.action==='export')exportTable();else if(d.action==='print')window.print();else if(d.action==='printReport'){openModal(titles[page],`<div class="invoice"><h2>${esc(db.settings.name)} — ${esc(titles[page])}</h2><p>Sample report · ${esc(today())}</p>${$('#content .tablewrap')?.outerHTML||''}</div><div class="formactions">${btn('Close','cancel','secondary')}${btn('Print / Save PDF','print','','print')}</div>`)}else if(d.action==='backup'){download(JSON.stringify(db,null,2),'bike-doctor-sample-backup.json','application/json');toast('Sample backup downloaded')}else if(d.action==='reset'){search='';filter='';render()}else if(d.action==='addService'){jobDraft.record.serviceLines.push({service:'',charge:0});lineRender()}else if(d.action==='addPart'){jobDraft.record.partLines.push({part:'',qty:1,price:0,gst:0});lineRender()}});
document.addEventListener('change',e=>{if(!jobDraft)return;let d=e.target.dataset,b=jobDraft.record;if(d.line){let [kind,i]=d.line.split('|');if(kind==='service'){b.serviceLines[i]=autofillServiceLine(find('services',e.target.value),b.serviceLines[i],e.target.value)}else{let p=find('parts',e.target.value);b.partLines[i]=autofillPartLine(p,b.partLines[i],e.target.value,jobDraft.key,jobDraft.record.invoiceType)}lineRender()}if(d.partfield){let [i,key]=d.partfield.split('|');b.partLines[i][key]=Number(e.target.value);updateBillTotals()}if(d.charge!==undefined){b.serviceLines[Number(d.charge)].charge=Number(e.target.value);updateBillTotals()}});
