function splitDiscounts(b){let labour=(b.serviceLines||[]).reduce((s,l)=>s+Number(l.charge||0),0),parts=(b.partLines||[]).reduce((s,l)=>s+Number(l.qty||0)*Number(l.price||0),0);let service=round(b.serviceDiscountType==='percent'?labour*Number(b.serviceDiscount||0)/100:Number(b.serviceDiscount||0)),part=round(b.partsDiscountType==='percent'?parts*Number(b.partsDiscount||0)/100:Number(b.partsDiscount||0));return {labour,parts,service,part}}
function invoiceDiscount(b){let d=splitDiscounts(b);return round(d.service+d.part+Number(b.discount||0))}

