function autofillPartLine(part,line,id,key,invoiceType){let next={...line,part:id,name:part?.name||'',price:Number(part?.[key==='purchases'?'purchase':'price']||0),gst:Number(part?.gst??0)};delete next.sourceAmount;return next}
function autofillServiceLine(service,line,id){return {...line,service:id,name:service?.name||'',charge:Number(service?.charge||0)}}

/* Derive from purchase history so entry edits/removal never leave a stale copied date. */
function latestPartPurchaseDate(id){return (db.purchases||[]).filter(p=>p.status!=='Cancelled'&&/^\d{4}-\d{2}-\d{2}$/.test(p.date||'')&&(p.partLines||[]).some(line=>line.part===id&&Number(line.qty)>0)).map(p=>p.date).sort().pop()||''}
function partPurchaseDate(part){return latestPartPurchaseDate(part?.id)||part?.purchaseDate||''}

function uiDateTime(value){let d=new Date(value);return Number.isFinite(d.getTime())?d.toLocaleString('en-GB',{timeZone:'Asia/Kolkata',day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit',hour12:true}):'—'}

/* Vendor associations are derived from active supplier purchase entries, never copied to a stale master field. */
function partPurchaseVendors(partId){let map=new Map();for(let bill of db.purchases||[]){if(bill.status==='Cancelled')continue;let items=(bill.partLines||[]).filter(l=>l.part===partId&&Number(l.qty)>0);if(!items.length)continue;let labels=[...new Set(items.map(l=>String(l.vendor||bill.supplier||'').trim()).filter(Boolean))];for(let label of labels){label=label.replace(/\s+/g,' ');let key=label.toLocaleLowerCase();if(!map.has(key))map.set(key,{key,name:label,purchases:[]});map.get(key).purchases.push({id:bill.id,invoice:bill.invoice||'',date:bill.date||'',location:bill.stockLocation==='godown'?'Godown':'Main Stock',qty:round(items.filter(l=>String(l.vendor||bill.supplier||'').trim().toLocaleLowerCase()===key).reduce((n,l)=>n+Number(l.qty),0))})}}return [...map.values()].sort((a,b)=>a.name.localeCompare(b.name))}
function partVendorNames(partId){return [...new Set([find('parts',partId)?.preferredVendor,...partPurchaseVendors(partId).map(v=>v.name)].map(v=>String(v||'').trim()).filter(Boolean))].join(', ')}
function partVendorMarkup(partId){let preferred=String(find('parts',partId)?.preferredVendor||'').trim(),vendors=partPurchaseVendors(partId),shown=[];if(preferred)shown.push('<span class="partPreferredVendor">Preferred: '+esc(preferred)+'</span>');for(let v of vendors)if(v.name.toLocaleLowerCase()!==preferred.toLocaleLowerCase())shown.push('<button type="button" class="partVendorLink" data-part-vendor="'+esc(v.key)+'" data-part-vendor-sku="'+esc(partId)+'" title="View this vendor’s purchases for this part">'+esc(v.name)+'</button>');return shown.join('<br>')||'<small>No vendor selected</small>'}



/* Explicit keypad support for editable transaction amounts, including NumLock-off digit keys. */
document.addEventListener('focusin',e=>{if(e.target instanceof HTMLInputElement&&e.target.matches('[name="advance"]'))e.target.dataset.numpadFresh='1'});document.addEventListener('input',e=>{if(e.target instanceof HTMLInputElement&&e.target.matches('[name="advance"]')&&e.isTrusted)e.target.dataset.numpadFresh='0'});document.addEventListener('keydown',e=>{let el=e.target;if(!(el instanceof HTMLInputElement)||!el.matches('[data-charge],[data-partfield$="|price"],[data-item-discount$="|discount"],[name="advance"],[type="search"]')||e.ctrlKey||e.altKey||e.metaKey)return;let d=/^Numpad([0-9])$/.exec(e.code),decimal=e.code==='NumpadDecimal'||e.code==='NumpadComma';if(!d&&!decimal)return;e.preventDefault();if(el.matches('[name="advance"]')){if(el.readOnly)return;let fresh=el.dataset.numpadFresh==='1';if(decimal){if(!fresh&&el.value.includes('.'))return;el.value=fresh?'0.0':el.value?el.value+'.0':'0.0'}else{let digit=d[1];el.value=fresh||!el.value||el.value==='0'?digit:el.value+digit}el.dataset.numpadFresh='0';el.dispatchEvent(new Event('input',{bubbles:true}));return}if(decimal&&el.value.includes('.'))return;let start=el.selectionStart??el.value.length,end=el.selectionEnd??start;el.setRangeText(d?d[1]:'.',start,end,'end');el.dispatchEvent(new Event('input',{bubbles:true}))},true);


document.addEventListener('click',event=>{const button=event.target.closest('[data-purchase-add]');if(!button||typeof jobDraft==='undefined'||jobDraft?.key!=='purchases')return;event.preventDefault();event.stopImmediatePropagation();jobDraft.record.partLines=jobDraft.record.partLines||[];jobDraft.record.partLines.push({part:'',partCode:'',name:'',hsn:'',qty:1,price:0,gst:0,vendor:'',brand:''});if(typeof lineRender==='function')lineRender()},true);
